import { readFile, writeFile } from "node:fs/promises";

const source = new URL("../src/abonnements/assets/test-d-autonomie.pdf", import.meta.url);
const target = new URL("../convex/abo/testAutonomiePdf.ts", import.meta.url);
const base64 = (await readFile(source)).toString("base64");

await writeFile(
  target,
  [
    "// Generated by scripts/generate-test-autonomie-pdf.mjs from the official versioned PDF.",
    "// Do not edit by hand; rerun the generator after replacing the source form.",
    `export const TEST_AUTONOMIE_PDF_BASE64 = ${JSON.stringify(base64)};`,
    "",
  ].join("\n"),
);
